-- Verified, multi-valued cuisine enrichment for the restaurant directory.
-- Generated from 4049 restaurant records. Seed SHA-256: a583e76e1f6bcd8003a1ffc3b54784462c7fae28acad2e5588e8596c2ba6a4bb
-- Sources are retained per restaurant/cuisine pair; no category is inferred from an unverified web homonym.

BEGIN;

CREATE TABLE IF NOT EXISTS public.restaurant_cuisine_evidence (
  restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
  cuisine_id uuid NOT NULL REFERENCES public.cuisines(id) ON DELETE CASCADE,
  source_kind text NOT NULL,
  source_url text,
  source_label text,
  confidence numeric(4, 3) NOT NULL CHECK (confidence >= 0 AND confidence <= 1),
  evidence jsonb NOT NULL DEFAULT '{}'::jsonb,
  verified_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (restaurant_id, cuisine_id, source_kind)
);

ALTER TABLE public.restaurant_cuisine_evidence ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.restaurant_cuisine_evidence FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.restaurant_cuisine_evidence TO service_role;

CREATE INDEX IF NOT EXISTS restaurant_cuisine_evidence_source_idx
  ON public.restaurant_cuisine_evidence(source_kind, verified_at DESC);

CREATE TABLE IF NOT EXISTS public.restaurant_directory_cuisine_jobs (
  restaurant_id uuid PRIMARY KEY REFERENCES public.restaurants(id) ON DELETE CASCADE,
  status text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'processing', 'success', 'not_found', 'error')),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 5),
  last_attempt_at timestamptz,
  next_attempt_at timestamptz,
  locked_at timestamptz,
  source_page_url text,
  evidence_count integer NOT NULL DEFAULT 0 CHECK (evidence_count >= 0),
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.restaurant_directory_cuisine_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.restaurant_directory_cuisine_jobs FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.restaurant_directory_cuisine_jobs TO service_role;

CREATE INDEX IF NOT EXISTS restaurant_directory_cuisine_jobs_due_idx
  ON public.restaurant_directory_cuisine_jobs(status, next_attempt_at, attempts, created_at)
  WHERE status IN ('pending', 'processing', 'not_found', 'error');

