INSERT INTO public.cuisines (name, slug, keywords)
SELECT seed.name, seed.slug, seed.keywords
FROM _directory_cuisine_taxonomy seed
WHERE NOT EXISTS (
  SELECT 1
  FROM public.cuisines existing
  WHERE existing.slug = seed.slug OR lower(existing.name) = lower(seed.name)
);

UPDATE public.cuisines cuisine
SET slug = CASE
      WHEN cuisine.slug IS NOT NULL THEN cuisine.slug
      WHEN NOT EXISTS (
        SELECT 1 FROM public.cuisines other
        WHERE other.slug = seed.slug AND other.id <> cuisine.id
      ) THEN seed.slug
      ELSE cuisine.slug
    END,
    keywords = (
      SELECT ARRAY(
        SELECT DISTINCT keyword
        FROM unnest(COALESCE(cuisine.keywords, '{}'::text[]) || seed.keywords) AS keyword
        WHERE NULLIF(btrim(keyword), '') IS NOT NULL
        ORDER BY keyword
      )
    ),
    archived_at = NULL,
    archived_by = NULL,
    archive_reason = NULL
FROM _directory_cuisine_taxonomy seed
WHERE cuisine.slug = seed.slug OR lower(cuisine.name) = lower(seed.name);

