  seed.restaurant_id::uuid,
  cuisine.id,
  seed.source_kind,
  seed.source_url,
  seed.source_label,
  seed.confidence,
  seed.evidence,
  now(),
  now()
FROM _directory_cuisine_seed seed
JOIN public.restaurants restaurant ON restaurant.id = seed.restaurant_id::uuid
JOIN public.cuisines cuisine ON cuisine.slug = seed.cuisine_slug
ON CONFLICT (restaurant_id, cuisine_id, source_kind) DO UPDATE
SET source_url = EXCLUDED.source_url,
    source_label = EXCLUDED.source_label,
    confidence = EXCLUDED.confidence,
    evidence = EXCLUDED.evidence,
    verified_at = EXCLUDED.verified_at,
    updated_at = now();

INSERT INTO public.restaurant_cuisines (restaurant_id, cuisine_id)
SELECT DISTINCT evidence.restaurant_id, evidence.cuisine_id
FROM public.restaurant_cuisine_evidence evidence
ON CONFLICT (restaurant_id, cuisine_id) DO NOTHING;

INSERT INTO public.restaurant_directory_cuisine_jobs (
  restaurant_id,
  status,
  evidence_count,
  next_attempt_at
)
SELECT
  restaurant.id,
  CASE WHEN count(restaurant_cuisine.cuisine_id) > 0 THEN 'success' ELSE 'pending' END,
  count(restaurant_cuisine.cuisine_id)::integer,
  CASE WHEN count(restaurant_cuisine.cuisine_id) > 0 THEN NULL ELSE now() END
FROM public.restaurants restaurant
LEFT JOIN public.restaurant_cuisines restaurant_cuisine ON restaurant_cuisine.restaurant_id = restaurant.id
WHERE restaurant.is_directory_listing IS TRUE
GROUP BY restaurant.id
ON CONFLICT (restaurant_id) DO UPDATE
SET status = CASE
      WHEN EXCLUDED.evidence_count > 0 THEN 'success'
      WHEN public.restaurant_directory_cuisine_jobs.status = 'success' THEN 'pending'
      ELSE public.restaurant_directory_cuisine_jobs.status
    END,
    evidence_count = EXCLUDED.evidence_count,
    next_attempt_at = CASE
      WHEN EXCLUDED.evidence_count > 0 THEN NULL
      ELSE COALESCE(public.restaurant_directory_cuisine_jobs.next_attempt_at, now())
    END,
    locked_at = CASE WHEN EXCLUDED.evidence_count > 0 THEN NULL ELSE public.restaurant_directory_cuisine_jobs.locked_at END,
    last_error = CASE WHEN EXCLUDED.evidence_count > 0 THEN NULL ELSE public.restaurant_directory_cuisine_jobs.last_error END,
    updated_at = now();

CREATE OR REPLACE FUNCTION public.service_claim_directory_cuisine_jobs(p_limit integer DEFAULT 3)
RETURNS TABLE(restaurant_id uuid)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 3), 1), 5);
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT job.restaurant_id
    FROM public.restaurant_directory_cuisine_jobs job
    JOIN public.restaurants restaurant ON restaurant.id = job.restaurant_id
    WHERE restaurant.is_directory_listing IS TRUE
      AND job.attempts < 5
      AND NOT EXISTS (
        SELECT 1 FROM public.restaurant_cuisines existing
        WHERE existing.restaurant_id = job.restaurant_id
      )
      AND (
        job.status IN ('pending', 'not_found', 'error')
        OR (job.status = 'processing' AND job.locked_at < now() - interval '15 minutes')
      )
      AND (job.next_attempt_at IS NULL OR job.next_attempt_at <= now())
    ORDER BY COALESCE(job.next_attempt_at, job.created_at), job.attempts, job.restaurant_id
    FOR UPDATE OF job SKIP LOCKED
    LIMIT v_limit
  )
  UPDATE public.restaurant_directory_cuisine_jobs job
  SET status = 'processing',
      attempts = job.attempts + 1,
      last_attempt_at = now(),
      locked_at = now(),
      next_attempt_at = NULL,
      last_error = NULL,
      updated_at = now()
  FROM candidates
  WHERE job.restaurant_id = candidates.restaurant_id
  RETURNING job.restaurant_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.service_claim_directory_cuisine_jobs(integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.service_claim_directory_cuisine_jobs(integer) TO service_role;

CREATE OR REPLACE FUNCTION public.service_apply_directory_cuisine_evidence(
  p_restaurant_id uuid,
  p_source_url text,
  p_assignments jsonb
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'service_role required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.restaurants
    WHERE id = p_restaurant_id AND is_directory_listing IS TRUE
  ) THEN
    RAISE EXCEPTION 'directory restaurant not found';
  END IF;
  IF jsonb_typeof(p_assignments) <> 'array' OR jsonb_array_length(p_assignments) > 12 THEN
    RAISE EXCEPTION 'invalid cuisine assignments';
  END IF;

  WITH submitted AS (
    SELECT DISTINCT
      NULLIF(btrim(item.slug), '') AS slug,
      NULLIF(btrim(item.label), '') AS label,
      LEAST(GREATEST(COALESCE(item.confidence, 0.9), 0), 1)::numeric(4, 3) AS confidence,
      COALESCE(item.evidence, '{}'::jsonb) AS evidence
    FROM jsonb_to_recordset(p_assignments) AS item(
      slug text,
      label text,
      confidence numeric,
      evidence jsonb
    )
    WHERE NULLIF(btrim(item.slug), '') IS NOT NULL
  ), inserted AS (
    INSERT INTO public.restaurant_cuisine_evidence (
      restaurant_id,
      cuisine_id,
      source_kind,
      source_url,
      source_label,
      confidence,
      evidence,
      verified_at,
      updated_at
    )
    SELECT
      p_restaurant_id,
      cuisine.id,
      'official_website_crawl',
      p_source_url,
      submitted.label,
      submitted.confidence,
      submitted.evidence,
      now(),
      now()
    FROM submitted
    JOIN public.cuisines cuisine ON cuisine.slug = submitted.slug AND cuisine.archived_at IS NULL
    ON CONFLICT (restaurant_id, cuisine_id, source_kind) DO UPDATE
    SET source_url = EXCLUDED.source_url,
        source_label = EXCLUDED.source_label,
        confidence = EXCLUDED.confidence,
        evidence = EXCLUDED.evidence,
        verified_at = EXCLUDED.verified_at,
        updated_at = now()
    RETURNING restaurant_id, cuisine_id
  )
  INSERT INTO public.restaurant_cuisines (restaurant_id, cuisine_id)
  SELECT restaurant_id, cuisine_id FROM inserted
  ON CONFLICT (restaurant_id, cuisine_id) DO NOTHING;

  SELECT count(*)::integer
  INTO v_count
  FROM public.restaurant_cuisine_evidence
  WHERE restaurant_id = p_restaurant_id;

  UPDATE public.restaurant_directory_cuisine_jobs
  SET status = CASE WHEN v_count > 0 THEN 'success' ELSE 'not_found' END,
      evidence_count = v_count,
      source_page_url = p_source_url,
      next_attempt_at = CASE WHEN v_count > 0 THEN NULL ELSE now() + interval '30 days' END,
      locked_at = NULL,
      last_error = CASE WHEN v_count > 0 THEN NULL ELSE 'no_verified_cuisine_on_official_site' END,
      updated_at = now()
  WHERE restaurant_id = p_restaurant_id;

  RETURN v_count;
END;
$function$;

REVOKE ALL ON FUNCTION public.service_apply_directory_cuisine_evidence(uuid, text, jsonb)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.service_apply_directory_cuisine_evidence(uuid, text, jsonb)
  TO service_role;

CREATE OR REPLACE FUNCTION public.enqueue_directory_cuisine_research()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.is_directory_listing IS TRUE THEN
    INSERT INTO public.restaurant_directory_cuisine_jobs (
      restaurant_id,
      status,
      attempts,
      next_attempt_at,
      last_error
    )
    VALUES (NEW.id, 'pending', 0, now(), NULL)
    ON CONFLICT (restaurant_id) DO UPDATE
    SET status = 'pending',
        attempts = 0,
        next_attempt_at = now(),
        locked_at = NULL,
        last_error = NULL,
        updated_at = now()
    WHERE NOT EXISTS (
      SELECT 1 FROM public.restaurant_cuisines existing
      WHERE existing.restaurant_id = NEW.id
    );
  END IF;
  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.enqueue_directory_cuisine_research() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS restaurants_enqueue_directory_cuisine_research ON public.restaurants;
CREATE TRIGGER restaurants_enqueue_directory_cuisine_research
AFTER INSERT OR UPDATE OF name, address, city, directory_source_reference, is_directory_listing
ON public.restaurants
FOR EACH ROW
EXECUTE FUNCTION public.enqueue_directory_cuisine_research();

CREATE OR REPLACE FUNCTION public.mark_directory_cuisine_job_satisfied()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.restaurants
    WHERE id = NEW.restaurant_id AND is_directory_listing IS TRUE
  ) THEN
    SELECT count(*)::integer
    INTO v_count
    FROM public.restaurant_cuisines
    WHERE restaurant_id = NEW.restaurant_id;

    INSERT INTO public.restaurant_directory_cuisine_jobs (
      restaurant_id,
      status,
      evidence_count,
      next_attempt_at
    )
    VALUES (NEW.restaurant_id, 'success', v_count, NULL)
    ON CONFLICT (restaurant_id) DO UPDATE
    SET status = 'success',
        evidence_count = v_count,
        next_attempt_at = NULL,
        locked_at = NULL,
        last_error = NULL,
        updated_at = now();
  END IF;
  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.mark_directory_cuisine_job_satisfied() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS restaurant_cuisines_mark_directory_job_satisfied
  ON public.restaurant_cuisines;
CREATE TRIGGER restaurant_cuisines_mark_directory_job_satisfied
AFTER INSERT ON public.restaurant_cuisines
FOR EACH ROW
EXECUTE FUNCTION public.mark_directory_cuisine_job_satisfied();

CREATE EXTENSION IF NOT EXISTS pg_cron;
CREATE EXTENSION IF NOT EXISTS pg_net;

DO $schedule$
DECLARE
  v_secret text;
  v_base text := 'https://wwcrtyoueexyxkkikaos.supabase.co/functions/v1';
BEGIN
  SELECT decrypted_secret
  INTO v_secret
  FROM vault.decrypted_secrets
  WHERE name = 'internal_cron_secret'
  LIMIT 1;

  IF NULLIF(v_secret, '') IS NULL THEN
    RAISE NOTICE 'Vault secret internal_cron_secret absent: tok-directory-cuisine-enrichment not scheduled.';
    RETURN;
  END IF;

  PERFORM cron.unschedule('tok-directory-cuisine-enrichment')
  WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'tok-directory-cuisine-enrichment');

  PERFORM cron.schedule('tok-directory-cuisine-enrichment', '* * * * *', format($cron$
    SELECT net.http_post(
      url := %L,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-internal-cron-secret', %L
      ),
      body := '{"mode":"process_batch","limit":3,"source":"cron"}'::jsonb,
      timeout_milliseconds := 55000
    );
  $cron$, v_base || '/enrich-directory-cuisines', v_secret));
END;
$schedule$;

NOTIFY pgrst, 'reload schema';

COMMIT;
